insert into public.lines (collection, category, title, text, position, best_situation, difficulty, confidence_required, responses, voice_delivery, red_flags, alternatives, success_estimate) values
('opener', 'Fun & Playful', NULL, 'What’s something that always makes your day better?', 1, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['Great coffee and a quiet morning.', 'Music in the car. Yours?']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t interrogate; answer your own question too.', array['What small thing never fails to cheer you up?']::text[], 72),
('opener', 'Fun & Playful', NULL, 'What’s the most spontaneous thing you’ve ever done?', 2, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['Booked a flight the same night.', 'Jumped into a lake in October.']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t try to top her story.', array['When did you last do something totally on impulse?']::text[], 66),
('opener', 'Fun & Playful', NULL, 'What’s a tiny thing you absolutely love that most people overlook?', 3, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['The smell of rain.', 'Handwritten notes. You?']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t call her answer silly.', array['What small detail in everyday life do you secretly adore?']::text[], 62),
('opener', 'Fun & Playful', NULL, 'Which movie character are you secretly most like?', 4, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['Probably the sidekick, honestly.', 'Ron Swanson. Don’t judge.']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t argue with her pick.', array['If your life were a movie, which character would you play?']::text[], 72),
('opener', 'Fun & Playful', NULL, 'What would your friends say is your superpower?', 5, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['They say I’m the planner.', 'Finding the best food anywhere.']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t fish for a compliment.', array['What do friends always come to you for?']::text[], 69),
('opener', 'Fun & Playful', NULL, 'What’s your most unpopular opinion?', 6, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['Pineapple on pizza is fine.', 'Mornings are overrated.']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t debate hard if she disagrees.', array['What do you believe that most people would argue with?']::text[], 73),
('opener', 'Fun & Playful', NULL, 'What’s the funniest thing that’s happened to you recently?', 7, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['I locked myself out in a towel.', 'My dog stole my sandwich.']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t laugh at her instead of with her.', array['Tell me about a moment lately that made you laugh out loud.']::text[], 68),
('opener', 'Fun & Playful', NULL, 'Which city surprised you the most?', 8, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['Lisbon. Way hillier than I thought.', 'Singapore. So much more green.']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t put her city down.', array['Which place turned out totally different from what you expected?']::text[], 71),
('opener', 'Fun & Playful', NULL, 'What’s the best piece of advice you’ve ever received?', 9, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['Sleep on big decisions.', 'Be kind, it’s free.']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t turn it into a lecture.', array['What advice stuck with you the longest?']::text[], 66),
('opener', 'Fun & Playful', NULL, 'What’s something you could talk about for hours?', 10, 'Cafés, events, groups, the first chat on an app', 'Easy', 2, array['Space travel, for hours.', 'Bad movies. Seriously.']::text[], 'Light and upbeat, a smile in your voice, medium pace', 'Don’t monologue; ask back.', array['What topic makes you lose track of time?']::text[], 69),
('opener', 'Emotional Connection', NULL, 'What’s something you’re genuinely proud of?', 11, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['Finishing my first marathon.', 'Starting my own little business.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t dismiss or one-up her answer.', array['What accomplishment means the most to you?']::text[], 62),
('opener', 'Emotional Connection', NULL, 'What experience changed how you see life?', 12, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['Moving abroad alone.', 'Losing someone. It changed my priorities.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t press for painful details.', array['What moment shifted your perspective?']::text[], 61),
('opener', 'Emotional Connection', NULL, 'What’s a dream you haven’t given up on?', 13, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['I still want to write a book.', 'Opening my own place someday.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t say it’s unrealistic.', array['What dream are you still quietly working toward?']::text[], 65),
('opener', 'Emotional Connection', NULL, 'What makes you feel most alive?', 14, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['Being outside with friends.', 'Live music, front row.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t switch topic abruptly.', array['When do you feel most like yourself?']::text[], 59),
('opener', 'Emotional Connection', NULL, 'What kind of people do you enjoy being around most?', 15, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['Honest, curious people.', 'People who laugh at themselves.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t list what you dislike in others.', array['What kind of person instantly makes you feel at ease?']::text[], 62),
('opener', 'Emotional Connection', NULL, 'What always puts you in a good mood?', 16, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['Running, always.', 'A good playlist.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t offer unrequested advice.', array['What’s your go-to mood booster?']::text[], 62),
('opener', 'Emotional Connection', NULL, 'What’s one thing you’d love to learn someday?', 17, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['Playing piano properly.', 'Speaking Italian.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t offer to teach her unasked.', array['What skill would you pick up with unlimited time?']::text[], 62),
('opener', 'Emotional Connection', NULL, 'What’s something you’ve become better at over the last years?', 18, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['Handling stress calmly.', 'Cooking something real.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t quiz her further.', array['What have you grown into over the last few years?']::text[], 66),
('opener', 'Emotional Connection', NULL, 'What are you most grateful for right now?', 19, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['My family, truly.', 'A really good week.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t make it about you.', array['What’s making you feel lucky lately?']::text[], 58),
('opener', 'Emotional Connection', NULL, 'What’s something people often misunderstand about you?', 20, 'After a few minutes of easy small talk, or in a chat that already feels warm', 'Medium', 3, array['People think I’m shy. I’m observing.', 'That I’m serious. I’m not.']::text[], 'Slower and warm, softer volume, a pause after the question', 'Don’t argue with how she sees herself.', array['What do people get wrong about you at first?']::text[], 56),
('opener', 'Adventure', NULL, 'If you could wake up anywhere tomorrow, where would it be?', 21, 'Travel spots, hostels, flights, any chat about weekends or holidays', 'Easy', 2, array['A cabin in the mountains.', 'Greece, with the sea in view.']::text[], 'Curious and energetic, descriptive', 'Don’t brag about your own picks.', array['Where would you teleport for a perfect morning?']::text[], 68),
('opener', 'Adventure', NULL, 'What destination is still on your bucket list?', 22, 'Travel spots, hostels, flights, any chat about weekends or holidays', 'Easy', 2, array['Japan, finally.', 'Patagonia.']::text[], 'Curious and energetic, descriptive', 'Don’t say you’ve been everywhere.', array['Which place are you still dreaming of visiting?']::text[], 62),
('opener', 'Adventure', NULL, 'What was your best trip ever?', 23, 'Travel spots, hostels, flights, any chat about weekends or holidays', 'Easy', 2, array['Portugal, two weeks, no plan.', 'A road trip along the coast.']::text[], 'Curious and energetic, descriptive', 'Don’t compare trips.', array['Which trip would you repeat in a heartbeat?']::text[], 70),
('opener', 'Adventure', NULL, 'What’s your perfect weekend?', 24, 'Travel spots, hostels, flights, any chat about weekends or holidays', 'Easy', 2, array['Slow morning, hike, good dinner.', 'A city break with great food.']::text[], 'Curious and energetic, descriptive', 'Don’t offer a plan too soon.', array['How would your ideal two days off look?']::text[], 69),
('opener', 'Adventure', NULL, 'Ocean, mountains or city?', 25, 'Travel spots, hostels, flights, any chat about weekends or holidays', 'Easy', 2, array['Mountains, always.', 'Ocean. I need the sound.']::text[], 'Curious and energetic, descriptive', 'Don’t pick the opposite just to joke.', array['Beach, forest or skyline?']::text[], 71)
