('opener', 'Deep Connection', NULL, 'What does a great relationship look like to you?', 32, 'Long one-to-one talks, a second date, late evening chats', 'Hard', 4, array['Teamwork and good communication.', 'Calm, with real adventures.']::text[], 'Calm, low and slow, steady eye contact, no rushing', 'Don’t describe your ex.', array['How would you describe a relationship that really works?']::text[], 56),
('opener', 'Deep Connection', NULL, 'What makes someone unforgettable?', 33, 'Long one-to-one talks, a second date, late evening chats', 'Hard', 4, array['Being fully present.', 'Kindness plus humor.']::text[], 'Calm, low and slow, steady eye contact, no rushing', 'Don’t answer with a cliché.', array['What do you remember most about people years later?']::text[], 51),
('opener', 'Deep Connection', NULL, 'What quality do you admire most in people?', 34, 'Long one-to-one talks, a second date, late evening chats', 'Hard', 4, array['Integrity.', 'Curiosity.']::text[], 'Calm, low and slow, steady eye contact, no rushing', 'Don’t say it’s what you have.', array['Which trait impresses you the most?']::text[], 54),
('opener', 'Deep Connection', NULL, 'What’s something you’ve learned the hard way?', 35, 'Long one-to-one talks, a second date, late evening chats', 'Hard', 4, array['Trust takes time.', 'Not everyone stays.']::text[], 'Calm, low and slow, steady eye contact, no rushing', 'Don’t offer to fix it.', array['What lesson cost you the most but was worth it?']::text[], 56),
('opener', 'Deep Connection', NULL, 'What’s more important: peace or excitement?', 36, 'Long one-to-one talks, a second date, late evening chats', 'Hard', 4, array['Peace, with some excitement.', 'Excitement. I get bored.']::text[], 'Calm, low and slow, steady eye contact, no rushing', 'Don’t imply one is better.', array['Would you rather have a calm life or an exciting one?']::text[], 57),
('opener', 'Deep Connection', NULL, 'What motivates you most in life?', 37, 'Long one-to-one talks, a second date, late evening chats', 'Hard', 4, array['Growth and people I love.', 'Doing meaningful work.']::text[], 'Calm, low and slow, steady eye contact, no rushing', 'Don’t dismiss her goals.', array['What gets you out of bed on hard days?']::text[], 47),
