('opener', 'Deep Connection', NULL, 'If your future self gave advice, what would it say?', 40, 'Long one-to-one talks, a second date, late evening chats', 'Hard', 4, array['Be patient with yourself.', 'Trust yourself earlier.']::text[], 'Calm, low and slow, steady eye contact, no rushing', 'Don’t answer for her.', array['What would you in ten years tell you today?']::text[], 48),
