('opener', 'Flirty', NULL, 'Do you trust your first impression of people?', 42, 'When there is clear mutual interest and a relaxed mood', 'Medium', 4, array['Mostly, yes.', 'I try to stay open.']::text[], 'Warm, a little slower, relaxed smile', 'Don’t score her answer.', array['How often is your first impression right?']::text[], 62),
('opener', 'Flirty', NULL, 'What’s more attractive: confidence or humor?', 43, 'When there is clear mutual interest and a relaxed mood', 'Medium', 4, array['Humor, but both help.', 'Confidence, if it’s relaxed.']::text[], 'Warm, a little slower, relaxed smile', 'Don’t fish for which one you are.', array['Confidence or humor: which one wins you over?']::text[], 56),
('opener', 'Flirty', NULL, 'What instantly makes someone interesting?', 44, 'When there is clear mutual interest and a relaxed mood', 'Medium', 4, array['Curiosity.', 'A good story.']::text[], 'Warm, a little slower, relaxed smile', 'Don’t interrupt with your own.', array['What makes someone worth talking to right away?']::text[], 56),
('opener', 'Flirty', NULL, 'What’s your idea of great chemistry?', 45, 'When there is clear mutual interest and a relaxed mood', 'Medium', 4, array['When silence feels easy.', 'Laughing at the same things.']::text[], 'Warm, a little slower, relaxed smile', 'Don’t claim you already have it.', array['How do you know when there is real chemistry?']::text[], 64),
('opener', 'Flirty', NULL, 'What makes a conversation unforgettable?', 46, 'When there is clear mutual interest and a relaxed mood', 'Medium', 4, array['When someone is really listening.', 'A random honest moment.']::text[], 'Warm, a little slower, relaxed smile', 'Don’t steer to romance too fast.', array['What turns a normal chat into a great one?']::text[], 59),
('opener', 'Flirty', NULL, 'What’s your favorite personality trait in someone?', 47, 'When there is clear mutual interest and a relaxed mood', 'Medium', 4, array['Kindness.', 'A quick sense of humor.']::text[], 'Warm, a little slower, relaxed smile', 'Don’t list your own traits.', array['Which personality trait wins you over every time?']::text[], 62),
('opener', 'Flirty', NULL, 'What kind of energy do you enjoy around you?', 48, 'When there is clear mutual interest and a relaxed mood', 'Medium', 4, array['Calm and playful.', 'Warm and curious.']::text[], 'Warm, a little slower, relaxed smile', 'Don’t call her your type.', array['What kind of vibe do you like to be around?']::text[], 64),
('opener', 'Flirty', NULL, 'What makes someone stand out from the crowd?', 49, 'When there is clear mutual interest and a relaxed mood', 'Medium', 4, array['Being genuinely themselves.', 'A good laugh.']::text[], 'Warm, a little slower, relaxed smile', 'Don’t flatter in return.', array['What sets someone apart for you?']::text[], 52),
