insert into public.lines (collection, category, title, text, position, best_situation, difficulty, confidence_required, responses, voice_delivery, red_flags, alternatives, success_estimate) values
('flirt', 'Warmth & attention', 'Genuine compliment on personality', 'I like how you make everyone feel included.', 1, 'Any conversation: in person, on calls and in texts', 'Easy', 2, array['Thank you, that’s sweet.', 'Really? I don’t hear that often.']::text[], 'Warm, steady, unhurried', 'Don’t pair it with a looks comment.', array['You’re really good at putting people at ease.']::text[], 69),
('flirt', 'Playfulness & humor', 'Playful teasing without disrespect', 'You’re a tea person? Bold choice. I’ll allow it.', 2, 'Relaxed settings (cafés, bars, parties) once there is rapport', 'Medium', 3, array['Wow, rude. Also fair.', 'I’ll get you back for that.']::text[], 'Light and quick with a smile; warm and slower when you are sincere', 'Don’t tease about looks or insecurities.', array['Okay, that’s a questionable choice. I respect it.']::text[], 56),
('flirt', 'Warmth & attention', 'Active listening', 'Nod, pause, then reflect: “So the hardest part was starting over?”', 3, 'Any conversation: in person, on calls and in texts', 'Easy', 2, array['You really listen, huh.', 'Yes, exactly that.']::text[], 'Warm, steady, unhurried', 'Don’t check your phone or interrupt.', array['So what you’re saying is…']::text[], 66),
('flirt', 'Depth & storytelling', 'Curiosity-based follow-up questions', 'What made you choose that path in the first place?', 4, 'Longer talks, dates, evening calls', 'Medium', 3, array['Funny story, actually.', 'I’ve never been asked that.']::text[], 'Varied tone, a pause before the key moment, lower on emotional parts', 'Don’t fire questions like an interview.', array['And how did that feel?']::text[], 67),
('flirt', 'Depth & storytelling', 'Storytelling instead of interviewing', 'Share a short story of yours, then ask about theirs.', 5, 'Longer talks, dates, evening calls', 'Medium', 3, array['Ha, that’s so you.', 'Wait, then what?']::text[], 'Varied tone, a pause before the key moment, lower on emotional parts', 'Don’t drag the story on.', array['That reminds me of a time…']::text[], 70),
('flirt', 'Warmth & attention', 'Eye contact', 'Hold it for two to three seconds, then smile and look away.', 6, 'Any conversation: in person, on calls and in texts', 'Easy', 2, array['(She holds it and smiles.)', '(She looks away, then back.)']::text[], 'Warm, steady, unhurried', 'Don’t stare without blinking.', array['Look while she answers, not only in pauses.']::text[], 76),
('flirt', 'Warmth & attention', 'Warm smile', 'Smile when you greet her, before you say anything.', 7, 'Any conversation: in person, on calls and in texts', 'Easy', 2, array['(She smiles back.)', 'You seem happy.']::text[], 'Warm, steady, unhurried', 'Don’t force the smile.', array['Smile with your eyes when you greet her.']::text[], 68),
('flirt', 'Playfulness & humor', 'Shared jokes', 'Build on something you both laughed at earlier.', 8, 'Relaxed settings (cafés, bars, parties) once there is rapport', 'Medium', 3, array['Haha, I’m still laughing about that.', 'Okay, that one’s ours now.']::text[], 'Light and quick with a smile; warm and slower when you are sincere', 'Don’t force a joke that has run out.', array['Bring back a funny moment from earlier.']::text[], 59),
('flirt', 'Warmth & attention', 'Referencing something she mentioned earlier', '“Did you try that ramen place you mentioned?”', 9, 'Any conversation: in person, on calls and in texts', 'Easy', 2, array['You remembered.', 'Yes! It was amazing.']::text[], 'Warm, steady, unhurried', 'Don’t use details that feel like stalking.', array['You said you love hiking. Where to next?']::text[], 74),
('flirt', 'Presence & delivery', 'Confident but relaxed body language', 'Open shoulders, relaxed hands, no fidgeting.', 10, 'Everywhere, especially first meetings and calls', 'Medium', 3, array['(She mirrors your posture.)', 'You look relaxed.']::text[], 'Slow, low and clear. Breathe before you speak.', 'Don’t cross your arms or fidget.', array['Stand tall with your hands visible.']::text[], 73),
('flirt', 'Playfulness & humor', 'Creating inside jokes', 'Give a funny moment a nickname and bring it back later.', 11, 'Relaxed settings (cafés, bars, parties) once there is rapport', 'Medium', 3, array['Oh no, not that again.', 'Haha, our thing.']::text[], 'Light and quick with a smile; warm and slower when you are sincere', 'Don’t exclude others with it.', array['Use the nickname once, lightly.']::text[], 67),
('flirt', 'Lead & intent', 'Showing passion for your life', 'Talk about something you love with real energy.', 12, 'When there is mutual interest and you want to suggest a next step', 'Hard', 4, array['I love hearing that.', 'You light up talking about it.']::text[], 'Clear, warm and direct. Let your sentences end on a falling tone.', 'Don’t talk about yourself for ten minutes.', array['Show it, then ask about her passion.']::text[], 55),
('flirt', 'Playfulness & humor', 'Light challenge conversations', '“Convince me that pineapple belongs on pizza.”', 13, 'Relaxed settings (cafés, bars, parties) once there is rapport', 'Medium', 3, array['Fine. Pitch me.', 'Challenge accepted.']::text[], 'Light and quick with a smile; warm and slower when you are sincere', 'Don’t challenge her values or identity.', array['Make me believe it in one sentence.']::text[], 57),
('flirt', 'Depth & storytelling', 'Future projection', '“If we ever go there, we have to try the night market.”', 14, 'Longer talks, dates, evening calls', 'Medium', 3, array['I’d like that.', 'Haha, big plans.']::text[], 'Varied tone, a pause before the key moment, lower on emotional parts', 'Don’t assume too much too early.', array['We should try that place sometime.']::text[], 66),
('flirt', 'Playfulness & humor', 'Playful assumptions', '“I bet you’re the one who plans every trip.”', 15, 'Relaxed settings (cafés, bars, parties) once there is rapport', 'Medium', 3, array['Wrong, but close.', 'How did you know?']::text[], 'Light and quick with a smile; warm and slower when you are sincere', 'Don’t assume negative things about her.', array['You seem like the person who…']::text[], 61),
('flirt', 'Playfulness & humor', 'Gentle role-playing', '“Okay, you’re the tour guide and I’m the clueless tourist.”', 16, 'Relaxed settings (cafés, bars, parties) once there is rapport', 'Medium', 3, array['Fine, I’ll play along.', 'Welcome to the tour.']::text[], 'Light and quick with a smile; warm and slower when you are sincere', 'Don’t push if she hesitates.', array['Pretend we’re critics at this restaurant.']::text[], 57),
('flirt', 'Depth & storytelling', 'Emotional storytelling', 'Tell a story and name how you felt at the turning point.', 17, 'Longer talks, dates, evening calls', 'Medium', 3, array['I’ve felt that too.', 'That sounds like it mattered.']::text[], 'Varied tone, a pause before the key moment, lower on emotional parts', 'Don’t overshare painful stuff.', array['Describe the feeling, not the details.']::text[], 67),
('flirt', 'Depth & storytelling', 'Thoughtful observations', '“You light up when you talk about your students.”', 18, 'Longer talks, dates, evening calls', 'Medium', 3, array['You noticed that?', 'That’s very true.']::text[], 'Varied tone, a pause before the key moment, lower on emotional parts', 'Don’t comment on her body.', array['I notice you listen before you speak.']::text[], 67),
('flirt', 'Depth & storytelling', 'Authentic vulnerability', '“I was nervous to say hi, honestly.”', 19, 'Longer talks, dates, evening calls', 'Medium', 3, array['I appreciate your honesty.', 'Same, actually.']::text[], 'Varied tone, a pause before the key moment, lower on emotional parts', 'Don’t dump heavy problems on her.', array['Truth is, I’m a bit nervous too.']::text[], 72),
('flirt', 'Presence & delivery', 'Positive energy', 'Bring warmth and interest, not complaints.', 20, 'Everywhere, especially first meetings and calls', 'Medium', 3, array['Your energy is nice.', 'I needed this today.']::text[], 'Slow, low and clear. Breathe before you speak.', 'Don’t force enthusiasm.', array['Share something good from your day.']::text[], 66),
('flirt', 'Presence & delivery', 'Calm speaking pace', 'Slow down by a quarter and pause between thoughts.', 21, 'Everywhere, especially first meetings and calls', 'Medium', 3, array['You’re so relaxed.', 'I like your calm.']::text[], 'Slow, low and clear. Breathe before you speak.', 'Don’t drag or sound bored.', array['Pause after each point.']::text[], 70),
